-- books.polascin.net: reconcile the production database with data/books.json,
-- 3 October 2026
--
-- 33 fields differed between the production database and data/books.json.
-- They were found by the new field-by-field parity test
-- (tools/tests/catalog-parity.test.cjs, "database and books.json agree field
-- by field"), which compares every rendered field per stable identifier
-- instead of comparing row counts. All of it predates 2026-10-03 and none of
-- it was part of the SK Nefro Baza 1 request.
--
-- Section A was applied after review; B, C and D are staged, not executed.
-- See STATUS below.
--
-- data/books.json is treated as canonical throughout: it is the fallback the
-- site serves when getDbConnection() fails, and it already holds the values
-- corrected by c25a628 / 4bd37ef on 2026-10-02.
--
-- Sections are independent. Apply only the ones you want.
--   A  web_url   5 rows  Google-search placeholders -> real author pages
--                1 row   empty -> https://www.polascin.net/
--             >> APPLIED 2026-10-03. The only section a visitor could see:
--                five "Author" buttons were opening a Google search page.
--   B  author    1 row   byline wording
--   C  url       4 rows  amzn.to shortlink -> direct /dp/ link, same ASIN
--             >> cosmetic; both forms land on the same ASIN
--   D  cover_image 22 rows  placeholder SVG -> real cover art / refreshed SVG
--             >> invisible today; catalog.php renders no images at all
--
-- Every statement matches on isbn, or on (isbn, title) for rows whose isbn is
-- the non-unique placeholder 'N/A' — never on the numeric id. No ISBN or ASIN
-- is modified.
--
-- Guards use the null-safe `NOT (col <=> 'value')` rather than `col <> 'value'`
-- so re-running is a no-op AND rows holding NULL are still updated. Plain `<>`
-- is the wrong tool here: `NULL <> 'x'` evaluates to NULL, not TRUE, so a
-- NULL row is silently skipped. That bit the Pravda.sk row on 2026-10-03,
-- whose web_url was NULL rather than ''.
--
-- STATUS 2026-10-03: section A has been APPLIED to production (all six rows,
-- verified: zero google-search web_url values remain). Sections B, C and D
-- were reviewed and deliberately NOT applied — see the note in
-- tools/tests/catalog-parity.test.cjs (ACCEPTED_DB_JSON_DIVERGENCE).
SET NAMES utf8mb4;

-- Full snapshot of every row touched below, for rollback. This runs BEFORE the
-- transaction on purpose: CREATE TABLE ... AS SELECT is DDL and implicitly
-- commits in MariaDB, so issuing it inside START TRANSACTION silently ends the
-- transaction and leaves the following UPDATEs running in autocommit.
CREATE TABLE IF NOT EXISTS books_backup_2026_10_03_parity AS SELECT * FROM books;

START TRANSACTION;

-- ---------------------------------------------------------------------------
-- A. web_url
-- ---------------------------------------------------------------------------
-- APPLIED 2026-10-03. Five records were serving a "google.com/search?q=..."
-- address as their secondary/author link — the same defect class fixed in `url` on 2026-10-02,
-- surviving in `web_url` because the guard then in place read `url` only.
-- The replacement values are the ones already in data/books.json: the Walter
-- Kyo Csoelle author store for the fiction titles, and the Lubomir Polascin
-- author page (cited in AGENTS.md, verified HTTP 200 on 2026-10-03) for
-- B07PKJBJJ7. The sixth row has an empty web_url where the JSON cites the
-- author's own site.

-- B0GGJXHQDH  (google-search placeholder)
UPDATE books SET web_url = 'https://www.amazon.com/stores/author/B0G2TCCJZZ'
  WHERE isbn = 'B0GGJXHQDH' AND NOT (web_url <=> 'https://www.amazon.com/stores/author/B0G2TCCJZZ');

-- B0FFGG4K4D  (google-search placeholder)
UPDATE books SET web_url = 'https://www.amazon.com/stores/author/B0G2TCCJZZ'
  WHERE isbn = 'B0FFGG4K4D' AND NOT (web_url <=> 'https://www.amazon.com/stores/author/B0G2TCCJZZ');

