  WHERE isbn = 'B0DHQY58C8' AND NOT (web_url <=> 'https://www.amazon.com/stores/author/B0G2TCCJZZ');

-- B07PKJBJJ7  (google-search placeholder)
UPDATE books SET web_url = 'https://www.amazon.com/Lubomir-Polascin/e/B07PN436VJ'
  WHERE isbn = 'B07PKJBJJ7' AND NOT (web_url <=> 'https://www.amazon.com/Lubomir-Polascin/e/B07PN436VJ');

-- Nefrológ Polaščín: Na zlyhanie obličiek by pacient v dnešnej dobe nemal zomrieť  (empty)
UPDATE books SET web_url = 'https://www.polascin.net/'
  WHERE isbn = 'N/A' AND title = 'Nefrológ Polaščín: Na zlyhanie obličiek by pacient v dnešnej dobe nemal zomrieť' AND NOT (web_url <=> 'https://www.polascin.net/');

-- ---------------------------------------------------------------------------
-- B. author   -- NOT APPLIED
-- ---------------------------------------------------------------------------
-- Nefrológ Polaščín: Na zlyhanie obličiek by pacient v dnešnej dobe nemal zomrieť
--   db   = Pravda.sk (Interview s Ľubomírom Polaščínom)
--   json = Interview in Pravda.sk with Ľubomír Polaščín
UPDATE books SET author = 'Interview in Pravda.sk with Ľubomír Polaščín'
  WHERE isbn = 'N/A' AND title = 'Nefrológ Polaščín: Na zlyhanie obličiek by pacient v dnešnej dobe nemal zomrieť' AND NOT (author <=> 'Interview in Pravda.sk with Ľubomír Polaščín');

